@spec patternEditor_writethrough_spec  src=tests/specs/patternEditor_writethrough_spec.lua  loc=316  cases=11
@exercises keyQueue (kq)
@surface   kq:fill
@harness   mk, reaper.GetMediaItemTake_Track

# Intent
  design/fx-patterns.md P3.5: write-through commit; curve normalises pb thousandths back to bipolar.
  Drives the real edit -> flush -> rebuild -> write-through path against a fake imgui.

# Helpers
  @fn keyId(name)  @ 13-22
  @fn setKeys(keys, mods)  @ 50-54
      -- The mini editor runs inside the modal the fill records as owner, and claims under that
      -- name, so the queue each pass reads is filled as one. See docs/keyQueue.md § Ownership.
  @fn loadPE(deps)  @ 60-68
  @fn notesBody()  @ 76-87
  @fn openNotesBody()  @ 90-98
      -- An OPEN first note followed by a finite one: readback must clip the open tail to the successor.
  @fn polyNotesBody()  @ 102-110
      -- Two overlapping notes on distinct lanes: a poly open keeps them apart; a mono open crushes them
      -- onto lane 1, where the readback clip serialises them as a monophonic run.
  @fn curveBody()  @ 112-121
  @fn ccCurveBody()  @ 124-133
      -- cc-domain curve: points ride a fixed scratch cc verbatim (0..127), no normalisation.
  @fn withEditor(harness, body, poly)  @ 137-143
      -- Open the editor on `body`, capturing each write-through commit; get() reads the latest.
      -- `poly` rides into pe:open: true authors overlapping lanes, absent/false pins everything to lane 1.
  @fn pressDelete(pe)  @ 146-149
      -- Delete the event under the (default row-0) cursor via the real dispatch path.
  @fn approx(a, b)  @ 151

# Cases
  @case 'a checkout edit writes through the commit callback, stripped to the whitelist'  [harness]  @ 155-170
  @case 'readback clips an OPEN note to its successor onset, not the loop length'  [harness]  @ 174-185
  @case 'a curve edit persists as normalised bipolar points, not raw thousandths'  [harness]  @ 189-204
  @case 'a cc-domain curve persists its points verbatim, echoing the domain'  [harness]  @ 208-224
  @case 'Enter commits: the edit stays in the store'  [harness]  @ 228-235
  @case 'Esc cancels: the store is restored to the open snapshot'  [harness]  @ 239-248
  @case 'close does not clobber the committed body via the unbind rebuild'  [harness]  @ 252-259
  @case 'a poly open keeps each authored lane through readback'  [harness]  @ 263-276
  @case 'the same body opened mono flattens every note onto lane 1'  [harness]  @ 280-289
  @case 'the body rpb seeds the editor and rides readback'  [harness]  @ 295-304
  @case 'a body with no rpb commits the default 4'  [harness]  @ 308-314

# Uses (outbound edges)
  @use call kq:fill  @ 53

